import { mkdir, mkdtemp, readFile, realpath, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { describe, expect, it } from "vitest";
import { hookTypes } from "./hook-types.js";

const TARGET = "types/hook-types.d.ts";

const TEMPLATE = {
  hookTypes: TARGET,
  hooks: {
    PreToolUse: [{
      hooks: [{ type: "mcp_tool", server: "s", tool: "t", input: { path: "${tool_input.file_path}" } }],
    }],
  },
};

const SOURCE = [
  "// Generated by claude-code-hook-types from the hooks template. Do not edit.",
  "export interface McpToolHookInputs {",
  `  "s": {`,
  `    "t": { "path": string };`,
  "  };",
  "}",
  "",
].join("\n");

// Writes hooks.template.json (plus extra files) into a fresh directory and returns the template path.
async function project(template: unknown, files: Record<string, string> = {}): Promise<string> {
  const root = await realpath(await mkdtemp(join(tmpdir(), "cch-")));
  const templatePath = join(root, "hooks.template.json");
  await writeFile(templatePath, JSON.stringify(template));
  for (const [file, content] of Object.entries(files)) {
    await mkdir(dirname(join(root, file)), { recursive: true });
    await writeFile(join(root, file), content);
  }
  return templatePath;
}

const read = (templatePath: string): Promise<string> => readFile(join(dirname(templatePath), TARGET), "utf8");

describe("hookTypes", () => {
  it("writes the file and its directory, then reports it up to date", async () => {
    const templatePath = await project(TEMPLATE);
    expect(await hookTypes(templatePath, false)).toEqual({ code: 0, lines: [`wrote "${TARGET}"`] });
    expect(await read(templatePath)).toBe(SOURCE);
    expect(await hookTypes(templatePath, false)).toEqual({ code: 0, lines: [`"${TARGET}" is up to date`] });
  });

  it("passes --check on a matching file", async () => {
    const templatePath = await project(TEMPLATE, { [TARGET]: SOURCE });
    expect(await hookTypes(templatePath, true)).toEqual({ code: 0, lines: [`"${TARGET}" is up to date`] });
  });

  it("fails --check on a missing file and writes nothing", async () => {
    const templatePath = await project(TEMPLATE);
    expect(await hookTypes(templatePath, true)).toEqual({
      code: 1,
      lines: [`error hook-types-stale: "${TARGET}" not found`],
    });
    await expect(read(templatePath)).rejects.toThrow(/ENOENT/);
  });

  it("fails --check on a stale file and leaves it unchanged", async () => {
    const templatePath = await project(TEMPLATE, { [TARGET]: "old\n" });
    expect(await hookTypes(templatePath, true)).toEqual({
      code: 1,
      lines: [`error hook-types-stale: "${TARGET}" is stale`],
    });
    expect(await read(templatePath)).toBe("old\n");
  });

  it("fails for a template without hookTypes", async () => {
    const templatePath = await project({ hooks: {} });
    expect(await hookTypes(templatePath, false)).toEqual({
      code: 1,
      lines: [`error: hooks template "${templatePath}" has no valid "hookTypes" field`],
    });
  });

  it("fails for an invalid hookTypes value and lists its issue", async () => {
    const templatePath = await project({ hookTypes: "types.js", hooks: {} });
    expect(await hookTypes(templatePath, false)).toEqual({
      code: 1,
      lines: [
        `error: hooks template "${templatePath}" has no valid "hookTypes" field`,
        `error template-invalid: hookTypes "types.js": must be a relative path to a .ts, .mts or .d.ts file`,
      ],
    });
  });

  it("fails for an invalid mcp_tool hook and writes nothing", async () => {
    const templatePath = await project({
      hookTypes: TARGET,
      hooks: { PreToolUse: [{ hooks: [{ type: "mcp_tool", server: "s", tool: "t" }] }] },
    });
    expect(await hookTypes(templatePath, false)).toEqual({
      code: 1,
      lines: ["error hook-input-invalid: hooks.PreToolUse[0].hooks[0].input undefined: must be an object"],
    });
    await expect(read(templatePath)).rejects.toThrow(/ENOENT/);
  });

  it("fails for a missing or unparsable template", async () => {
    const missing = join(dirname(await project({})), "nope.json");
    const result = await hookTypes(missing, false);
    expect(result.code).toBe(1);
    expect(result.lines[0]).toMatch(/^error: cannot read hooks template ".*nope\.json": /);

    const broken = await project({});
    await writeFile(broken, "{");
    const parsed = await hookTypes(broken, false);
    expect(parsed.code).toBe(1);
    expect(parsed.lines[0]).toMatch(/^error: cannot read hooks template ".*hooks\.template\.json": /);
  });
});
